function CreateEffectSetPlayer(BMDStruct, ObjectStruct, ItemIndex, SetLevel)

	if CUSTOM_EFFECT_SETS_SWITCH == 0
	then
		return
	end
	
	local setInfo = CUSTOM_SET_EFFECTS[ItemIndex]

	if setInfo ~= nil then
		math.randomseed(os.time())
		
		for key in pairs(setInfo) do
			local effectInfo = setInfo[key]
			
			if (SetLevel >= effectInfo.ItemMinLevel and SetLevel <= effectInfo.ItemMaxLevel) then
				local randValue = 100
				
				if effectInfo.RandTime ~= 100 then
					randValue = math.random(1, 100)
				end
				
				if effectInfo.RandTime >= randValue then
					if effectInfo.EffectType == 0 then
						CreateSprite(BMDStruct, ObjectStruct, effectInfo.BonePlayer, effectInfo.EffectID, effectInfo.Size, effectInfo.R, effectInfo.B, effectInfo.G, effectInfo.PosX, effectInfo.PosY, effectInfo.PosZ)
					elseif effectInfo.EffectType == 1 then
						CreateParticle(BMDStruct, ObjectStruct, effectInfo.BonePlayer, effectInfo.EffectID, effectInfo.EffectLv, effectInfo.Size, effectInfo.R, effectInfo.B, effectInfo.G, effectInfo.PosX, effectInfo.PosY, effectInfo.PosZ)
					elseif effectInfo.EffectType == 2 then
						CreateSkill(BMDStruct, ObjectStruct, effectInfo.BonePlayer, effectInfo.EffectID, effectInfo.EffectLv, effectInfo.Size, effectInfo.R, effectInfo.B, effectInfo.G, effectInfo.PosX, effectInfo.PosY, effectInfo.PosZ)
					end
				end
			end
		end
	end
end